// Frontière de module explicite sans réseau ni service séparé
package com.dlr.orders;      // ne dépend que de son propre package
package com.dlr.billing;     // communique via une interface publique, pas la base d'orders

public interface BillingFacade {
    Invoice chargeForOrder(OrderId orderId); // appel en mémoire, transaction unique
}
